from __future__ import annotations
from typing import TypedDict, Union

from taf.ul.ue.sim.env_setup.utils.enums import SimConfigType


class SimulatorDictType(TypedDict):
    type: str
    connected_bts_id: int
    wtssim_alias: str
    egate_timeout: int
    check_wts_version: bool
    file: str
    api: int
    db: str


BTSDictType = TypedDict(
    "BTSDictType",
    {
        "bts_type": str,
        "host_id": int,
        "scfc": str,
        "vendor_params": Union[str, list, None],
        "rad_params": Union[str, list, None],
        "bts_recovery": bool,
        "recovery_snapshot": bool,
        "primary": bool,
        "secondary": bool,
        "COMMISSIONING_TIMEOUT": int,
    },
)


class RtgCusConfigType(TypedDict):
    file: str
    api: SimConfigType
    db: str


class CloudBTSDictType(TypedDict):
    bts_type: str
    host_id: int
    vcu_scfc: list[str]
    vdu_scfc: list[str]
    bts_recovery: bool
    recovery_snapshot: bool
